// Test-only generic native-array observer, not a YM2151 model or physical acceptance band.
package main
import("fmt";"math")
const native_w=2*math.Pi*4124/(1<<20)
type interval struct{First int `json:"first"`;End int `json:"end_exclusive"`}
type sine_fit struct{Beta [3]float64 `json:"cos_sin_dc"`;Bound [3]float64 `json:"known_synthetic_quantizer_coefficient_bound"`;Amplitude float64 `json:"amplitude"`;Radius float64 `json:"ac_bound_radius"`}
type observed struct{State string `json:"state"`;Markers []interval `json:"markers"`;Windows []interval `json:"interiors"`;Low *sine_fit `json:"low,omitempty"`;Middle *sine_fit `json:"middle,omitempty"`;Return *sine_fit `json:"return_diagnostic,omitempty"`;HoldRatio float64 `json:"heldout_error_over_known_synthetic_bound"`;ReturnRatio float64 `json:"return_error_over_known_synthetic_bound"`;HoldOK bool `json:"holdout_consistent"`;ReturnOK bool `json:"return_consistent"`;MiddleFitAllowed bool `json:"middle_fit_allowed"`;MiddleHoldRatio float64 `json:"middle_heldout_error_over_known_synthetic_bound"`;MiddleState string `json:"middle_state"`}
func observe(left,right []float64,final_start int,q float64,middle_fit bool)(observed,error){r:=observed{Markers:[]interval{},Windows:[]interval{},MiddleFitAllowed:middle_fit,MiddleState:"not_fitted_aggregate_overload"};if len(left)!=16384||len(right)!=16384||q<=0||!finite(q)||final_start<0||final_start>16384{return r,fmt.Errorf("invalid arrays/known synthetic q/bounds")};for _,v:=range[][]float64{left,right}{for _,x:=range v{if !finite(x)||x!=math.Trunc(x)||x< -32768||x>32767{return r,fmt.Errorf("invalid integral native PCM")}}};for i:=0;i<len(left);{if left[i]!=0{i++;continue};start:=i;for i<len(left)&&left[i]==0{i++};if i-start>=256{r.Markers=append(r.Markers,interval{start,i})}};if len(r.Markers)!=2{r.State="unqualified_marker_count";return r,nil};a,b:=r.Markers[0],r.Markers[1];r.Windows=[]interval{{128,a.First-128},{a.End+128,b.First-128},{max(b.End+128,final_start),len(right)}};for _,w:=range r.Windows{if w.End-w.First<1536{r.State="unqualified_short_interiors";return r,nil}};low,e:=fit_native(right,r.Windows[0].First,1024,q);if e!=nil{return r,e};r.Low=&low;if low.Amplitude<32||low.Amplitude<=8*low.Radius{r.State="unobservable_low_support";return r,nil};r.HoldRatio=prediction_ratio(right,r.Windows[0].First+1024,512,low,q);r.ReturnRatio=prediction_ratio(right,r.Windows[2].First,1536,low,q);r.HoldOK=r.HoldRatio<=1.000001;r.ReturnOK=r.ReturnRatio<=1.000001;ret,e:=fit_native(right,r.Windows[2].First,1024,q);if e!=nil{return r,e};r.Return=&ret;if middle_fit{mid,e:=fit_native(right,r.Windows[1].First,1024,q);if e!=nil{return r,e};r.Middle=&mid;r.MiddleHoldRatio=prediction_ratio(right,r.Windows[1].First+1024,512,mid,q);r.MiddleState="fixed_frequency_middle_holdout_consistent";if r.MiddleHoldRatio>1.000001{r.MiddleState="middle_unstable"}};r.State="supported_generic_low_reference";if !r.HoldOK{r.State="holdout_inconsistent"}else if !r.ReturnOK{r.State="return_inconsistent"};return r,nil}
func fit_native(v []float64,start,count int,q float64)(sine_fit,error){r:=sine_fit{};if start<0||count<3||start+count>len(v){return r,fmt.Errorf("fit bounds")};var gram [3][6]float64;var rhs [3]float64;for i:=start;i<start+count;i++{x:=basis(i);for a:=0;a<3;a++{rhs[a]+=x[a]*v[i];for b:=0;b<3;b++{gram[a][b]+=x[a]*x[b]}}};for a:=0;a<3;a++{gram[a][a+3]=1};for col:=0;col<3;col++{pivot:=col;for row:=col+1;row<3;row++{if math.Abs(gram[row][col])>math.Abs(gram[pivot][col]){pivot=row}};if math.Abs(gram[pivot][col])<1e-12{return r,fmt.Errorf("singular basis")};gram[pivot],gram[col]=gram[col],gram[pivot];scale:=gram[col][col];for j:=0;j<6;j++{gram[col][j]/=scale};for row:=0;row<3;row++{if row==col{continue};scale=gram[row][col];for j:=0;j<6;j++{gram[row][j]-=scale*gram[col][j]}}};for a:=0;a<3;a++{for b:=0;b<3;b++{r.Beta[a]+=gram[a][b+3]*rhs[b]};for i:=start;i<start+count;i++{x:=basis(i);weight:=0.;for b:=0;b<3;b++{weight+=gram[a][b+3]*x[b]};r.Bound[a]+=(q/2)*math.Abs(weight)}};r.Amplitude=math.Hypot(r.Beta[0],r.Beta[1]);r.Radius=math.Hypot(r.Bound[0],r.Bound[1]);return r,nil}
func basis(n int)[3]float64{return [3]float64{math.Cos(native_w*float64(n)),math.Sin(native_w*float64(n)),1}}
func prediction_ratio(v []float64,start,count int,f sine_fit,q float64)float64{ratio:=0.;for n:=start;n<start+count;n++{x:=basis(n);prediction,bound:=0.,q/2;for j:=0;j<3;j++{prediction+=x[j]*f.Beta[j];bound+=math.Abs(x[j])*f.Bound[j]};ratio=math.Max(ratio,math.Abs(v[n]-prediction)/bound)};return ratio}
func gain_interval(f observed)(float64,float64,float64,bool){if !f.HoldOK||!f.ReturnOK||f.Low==nil||f.Middle==nil||f.Low.Amplitude<=f.Low.Radius||f.Middle.Amplitude<32||f.Middle.Amplitude<=8*f.Middle.Radius||f.MiddleState!="fixed_frequency_middle_holdout_consistent"{return 0,0,0,false};a,b:=f.Low,f.Middle;estimate:=b.Amplitude/a.Amplitude;lo:=math.Max(0,b.Amplitude-b.Radius)/(a.Amplitude+a.Radius);hi:=(b.Amplitude+b.Radius)/(a.Amplitude-a.Radius);return estimate,lo,hi,true}
func scalar_closure(f observed,g,lo,hi float64)(float64,bool){if !f.HoldOK||!f.ReturnOK||f.Low==nil||f.Middle==nil||f.Middle.Amplitude<32||f.Middle.Amplitude<=8*f.Middle.Radius||f.MiddleState!="fixed_frequency_middle_holdout_consistent"{return 0,false};a,b:=f.Low,f.Middle;distance:=math.Hypot(b.Beta[0]-g*a.Beta[0],b.Beta[1]-g*a.Beta[1]);bound:=b.Radius+hi*a.Radius+math.Max(g-lo,hi-g)*a.Amplitude;return distance/bound,distance<=bound*1.000001}
func finite(v float64)bool{return !math.IsNaN(v)&&!math.IsInf(v,0)}
